with with_prev as (select *, lag(txn_time) over (partition by txn_type order by txn_time, id) as prev_txn_time from transactions), gaps as (select *, case when prev_txn_time is null or txn_time > prev_txn_time + interval 90 days then 1 else 0 end as is_new_burst from with_prev) select *, sum(is_new_burst) over (partition by txn_type order by txn_time, id rows between unbounded preceding and current row) as burst_id from gaps
